package com.jinloes.practice;
import java.util.*; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: sorted lists separated by semicolons, for example: [4,10,15];[1,12,20];[6,14,24]"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } assertThat(Solution.smallestRange(List.of(List.of(4,10,15),List.of(1,12,20),List.of(6,14,24)))).containsExactly(12,15); assertThat(Solution.smallestRange(List.of(List.of(1,2,3),List.of(1,2,3)))).containsExactly(1,1); assertThat(Solution.smallestRange(List.of(List.of(5),List.of(0,10)))).containsExactly(0,5); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ System.out.println(Arrays.toString(Solution.smallestRange(parse(input)))); }catch(RuntimeException e){ System.out.println(USAGE); } } static List<List<Integer>> parse(String input){ List<List<Integer>> out=new ArrayList<>(); for(String part:input.split(";")){ String c=part.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) throw new IllegalArgumentException(); out.add(Arrays.stream(c.split("\\s+")).map(Integer::parseInt).toList()); } return out; } }
